import Notifee, { AndroidImportance, EventType, type Event } from '@notifee/react-native'
import BackgroundService from 'react-native-background-actions'
import { whenRouterReady } from '@/utils/whenRouterReady'
import * as Linking from 'expo-linking'
import { logCallDebug, logCallError } from '@/utils/call-debug'

export const NOTIFICATION_CHANNEL_ID = 'incoming_call'
export const MISSED_CALLS_NOTIFICATION_CHANNEL_ID = 'missed.calls'

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms))

export async function setNotifeeNotificationService() {
  logCallDebug('NOTIFEE_SERVICE_SETUP_START')
  await createNotificationChannels()
  Notifee.registerForegroundService((notification: unknown) => new Promise(() => notification))
  registerNotificationEventHandlers()
  logCallDebug('NOTIFEE_SERVICE_SETUP_COMPLETE')
}

// Create notification channels
const createNotificationChannels = async () => {
  logCallDebug('NOTIFEE_CHANNEL_CREATE_START', {
    channelId: NOTIFICATION_CHANNEL_ID,
    missedChannelId: MISSED_CALLS_NOTIFICATION_CHANNEL_ID,
  })
  await Notifee.createChannel({
    name: 'Call Notifications',
    id: NOTIFICATION_CHANNEL_ID,
    importance: AndroidImportance.HIGH,
    sound: 'default',
  })

  await Notifee.createChannel({
    name: 'Missed Calls',
    id: MISSED_CALLS_NOTIFICATION_CHANNEL_ID,
    importance: AndroidImportance.DEFAULT,
  })
  logCallDebug('NOTIFEE_CHANNEL_CREATE_COMPLETE')
}

// Set up event handlers for notification actions
const registerNotificationEventHandlers = () => {
  const onNotificationAction = async ({ type, detail }: Event) => {
    const { notification, pressAction } = detail
    logCallDebug('NOTIFEE_EVENT_RECEIVED', {
      type,
      notificationId: notification?.id,
      pressActionId: pressAction?.id,
      data: notification?.data,
    })

    if (type === EventType.PRESS) {
      const url = detail.notification?.data?.url
      if (url) {
        // Open the specified deeplink in Expo
        logCallDebug('NOTIFEE_EVENT_OPEN_URL', { url })
        Linking.openURL(Linking.createURL(String(url)))
      }
      //
    }

    // CASE 1: Handle call notification action buttons (accept/decline)
    if (type === EventType.ACTION_PRESS && notification?.data?.call) {
      // Legacy call action handling — currently a no-op.
<<<<<<< HEAD
      logCallDebug('NOTIFEE_EVENT_LEGACY_CALL_ACTION', {
        notificationId: notification?.id,
        pressActionId: pressAction?.id,
        data: notification.data,
      })
=======
>>>>>>> 359b34d
    }

    // CASE 2: Handle end ongoing call action
    if (type === EventType.ACTION_PRESS && pressAction?.id === 'end-ongoing') {
      // await directCall.end()
      logCallDebug('NOTIFEE_EVENT_END_ONGOING_ACTION', {
        notificationId: notification?.id,
      })
    }

    // CASE 3: Handle missed call notification taps
    if (type === EventType.PRESS && notification?.id?.startsWith('missed-')) {
      logCallDebug('NOTIFEE_EVENT_MISSED_CALL_PRESS', {
        notificationId: notification.id,
      })
      whenRouterReady((router: { push: (path: string) => void }) => {
        router.push('/')
      })
    }
  }

  // Register handlers for both states
  Notifee.onBackgroundEvent(onNotificationAction)
  Notifee.onForegroundEvent(onNotificationAction)
  logCallDebug('NOTIFEE_EVENT_HANDLERS_REGISTERED')
}

// Display ongoing call notification
export const displayOngoingCallNotification = async (
  callId: string,
  callerName = 'NAME HERE',
  isVideo = false
) => {
  logCallDebug('ONGOING_CALL_NOTIFICATION_START', {
    callId,
    callerName,
    isVideo,
  })
  const options = {
    taskName: 'Call',
    taskTitle: `Ongoing call with ${callerName}`,
    taskDesc: isVideo ? 'Video call in progress' : 'Voice call in progress',
    taskIcon: {
      name: 'ic_launcher',
      type: 'mipmap',
    },
    color: '#000000',
    linkingURI: `zing://calling-screen`,
    parameters: {
      delay: 1000,
      callId: callId,
      callerName: callerName,
      isVideo: isVideo,
    },
  }

  try {
    // Check if service is already running and stop it first
    if (await BackgroundService.isRunning()) {
      logCallDebug('ONGOING_CALL_NOTIFICATION_STOP_EXISTING', { callId })
      await BackgroundService.stop()
    }

    // Proper background task implementation
    const ongoingCallTask = async (taskDataArguments?: { delay?: number }) => {
      const { delay } = taskDataArguments || {}

      // This is the correct pattern according to the documentation
      await new Promise<void>(async resolve => {
        // Keep running while the service is active
        while (BackgroundService.isRunning()) {
          logCallDebug('ONGOING_CALL_NOTIFICATION_TICK', { callId, callerName })
          await sleep(delay || 1000)
        }
        resolve()
      })
    }

    await BackgroundService.start(ongoingCallTask, options)
    logCallDebug('ONGOING_CALL_NOTIFICATION_STARTED', { callId })

    // Update notification description
    await BackgroundService.updateNotification({
      taskDesc: isVideo ? 'Video call in progress' : 'Voice call in progress',
    })
  } catch (error) {
    logCallError('ONGOING_CALL_NOTIFICATION_START_ERROR', error, { callId })
  }
}

export const hideOngoingCallNotification = async (call: unknown) => {
  logCallDebug('ONGOING_CALL_NOTIFICATION_HIDE_START', { call })

  try {
    // Check if the service is running
    const isRunning = await BackgroundService.isRunning()
    logCallDebug('ONGOING_CALL_NOTIFICATION_RUNNING_STATUS', { call, isRunning })

    if (isRunning) {
      await BackgroundService.stop()
      logCallDebug('ONGOING_CALL_NOTIFICATION_STOPPED', { call })

      // Verify it stopped
      const isStillRunning = await BackgroundService.isRunning()
      logCallDebug('ONGOING_CALL_NOTIFICATION_STOP_VERIFY', { call, isStillRunning })
    } else {
      logCallDebug('ONGOING_CALL_NOTIFICATION_NOT_RUNNING', { call })
    }
  } catch (error) {
    logCallError('ONGOING_CALL_NOTIFICATION_HIDE_ERROR', error, { call })
  }
}

export const displayBackendNotification = ({
  title = 'hi',
  body = 'yo',
  phone,
}: {
  title?: string
  body?: string
  phone: string
}) => {
  logCallDebug('BACKEND_NOTIFICATION_DISPLAY_LOCAL', { title, phone })
  Notifee.displayNotification({
    title: title || 'Notification',
    body: body || 'You have a new notification',
    android: {
      channelId: NOTIFICATION_CHANNEL_ID,
      pressAction: {
        id: 'default',
        launchActivity: 'default',
      },
    },
    data: {
      phone,
      url: `/contact?phone=${phone}`,
    },
  })
}

