function startOfferRetry() {
  stopOfferRetry()
  offerAttempts = 0
  offerRetryTimer = setTimeout(sendOfferRetry, OFFER_RETRY_INTERVAL)
}

async function sendOfferRetry() {
  const { state, pc, targetId, currentCallId, ws } = get()
  if (state !== 'calling' || !pc) return

  offerAttempts++
  if (offerAttempts >= MAX_OFFER_ATTEMPTS) {
    stopOfferRetry()
    endCall()
    return
  }

  // Regather ICE candidates periodically so a network change mid-ring
  // (WiFi -> cellular) doesn't leave us with stale candidates.
  if (offerAttempts % ICE_RESTART_EVERY === 0) {
    try {
      const restarted = await pc.createOffer({ iceRestart: true } as any)
      await pc.setLocalDescription(restarted)
    } catch (error) {
      console.error('[offerRetry] ICE restart failed:', error)
    }
  }

  if (ws?.readyState === WebSocket.OPEN && pc.localDescription) {
    ws.send(
      JSON.stringify({
        type: 'offer',
        to: targetId,
        callId: currentCallId,
        offer: pc.localDescription,
      })
    )
  }

  offerRetryTimer = setTimeout(sendOfferRetry, OFFER_RETRY_INTERVAL)
}

