import { Platform } from 'react-native'
import * as Contacts from 'expo-contacts'
import AsyncStorage from '@react-native-async-storage/async-storage'
import * as ExpoWidgets from 'expo-widgets'

import type { ContactsAdapter } from '@shared/store/contacts/types'
import type { Contact } from '@shared/store/contacts/types'
import { toE164OrRaw } from '@/utils/phone'

// iOS: App Group identifier for sharing data with the widget extension
const iosAppGroup = 'group.com.zingapp.app'

export const reactNativeAdapter: ContactsAdapter = {
  async requestContactsPermission(): Promise<'granted' | 'denied' | 'undetermined'> {
    const { status } = await Contacts.requestPermissionsAsync()
    return status
  },

  async getContactsFromDevice(): Promise<Array<{ name: string; phone: string; avatar_url?: string }>> {
    const { data } = await Contacts.getContactsAsync({
      fields: [Contacts.Fields.Name, Contacts.Fields.PhoneNumbers, Contacts.Fields.Image],
    })

    // Filter contacts which has phone available
    const nameAndPhone = data
      .filter(contact => {
        return contact.phoneNumbers !== undefined && contact.phoneNumbers.length > 0
      })
      .map(contact => {
        return {
          name: contact.name || '',
          // Normalize to E.164 so contacts match app users 1:1 server-side,
          // using the device region as the default for local-format numbers.
          phone: toE164OrRaw(contact.phoneNumbers![0].number || ''),
          avatar_url: contact.image?.uri,
        }
      })

    return nameAndPhone
  },

  getStorage() {
    return AsyncStorage
  },

  async updateWidgetContacts(contacts: Contact[]): Promise<void> {
    try {
      // Format contacts for widget to contain id and name fields
      const widgetContacts = contacts
        .filter(contact => contact.has_app && contact.phone)
        .sort((a, b) => Number(b.available) - Number(a.available))
        .map(contact => ({
          phone_number: contact.phone,
          phone: contact.phone,
          name: contact.name,
          is_available: contact.available,
        }))

      // Serialize to JSON string
      const contactsString = JSON.stringify({ contacts: widgetContacts })

      if (Platform.OS === 'ios') {
        // CAN ONLY DISPLAY 9 ITEMS IN LARGE MODE
        // AND 4 IN SMALL
        // as there is no scroll functionality
        ExpoWidgets.setWidgetData('widgetKey', contactsString, iosAppGroup)
        ExpoWidgets.refreshWidgets('widgettt')
      } else {
        // Android: SharedPreferences file "DATA", key "appData"
        ExpoWidgets.setWidgetData('appData', contactsString, 'DATA')
        ExpoWidgets.refreshWidgets()
      }
    } catch (error) {
      throw error
    }
  },

  refreshWidgets(): void {
    if (Platform.OS === 'ios') {
      ExpoWidgets.refreshWidgets('widgettt')
    } else {
      ExpoWidgets.refreshWidgets()
    }
  },
}

