// ContactCard.js - Functional wrapper component
import React, { useCallback, useMemo } from 'react'
import { Alert } from 'react-native'
import { useCallsStore } from '@/store/calls'
import { router } from 'expo-router'
import { Share } from 'react-native'
import ContactCardPresentation from './presentation'
// import { displayOngoingCallNotification } from '@/lib/notifications/local'

export default function ContactCard({ contact }) {
  const status = useMemo(() => {
    if (!contact.has_app) return 'not_invited'
    return contact.available ? 'available' : 'unavailable'
  }, [contact.has_app, contact.available])

  const handlePress = useCallback(() => {
    switch (status) {
      case 'available':
        router.push({
          pathname: '/calling-screen',
          params: {
            peerPhone: encodeURIComponent(contact.phone),
            initiate: true,
          },
        })
        // displayOngoingCallNotification()
        break
      case 'unavailable':
        Alert.alert('User Unavailable', `${contact.name} is currently unavailable.`)
        break
      case 'not_invited':
        handleInvite()
        break
      default:
        console.warn('Unknown status:', status)
    }
  }, [status, contact])

  const handleInvite = useCallback(async () => {
    const inviteMessage = `Hey! I'm using Buzz Buzz to stay connected. Join me: [APP_STORE_LINK]`

    try {
      await Share.share({
        message: inviteMessage,
        title: 'Join me on Buzz Buzz',
      })
    } catch (error) {
      Alert.alert('Error', 'Failed to share invite.')
    }
  }, [])

  const statuses = {
    available: {
      color: '#4CEA94', // 20
      text: 'is available for a buzz',
    },
    unavailable: {
      color: '#EA4C4C', // 20
      text: "isn't available right now",
    },
    not_invited: {
      color: '#FFFFFF', // 40 and 20
      text: 'invite them to use buzz buzz',
    },
  }

  return (
    <ContactCardPresentation
      name={contact.name}
      phone={contact.phone}
      statusText={statuses[status].text}
      status={status}
      color={statuses[status].color}
      onPress={handlePress}
      avatarUrl={contact.avatar_url || contact.app_avatar_url}
      onLongPress={() => {
        router.push({
          pathname: '/contact',
          params: {
            phone: encodeURIComponent(contact.phone),
          },
        })
      }}
    />
  )
}

