import type { ContactsAdapter } from '@shared/store/contacts/adapter/types'

// Web localStorage wrapper to match AsyncStorage API
const webStorage = {
  getItem: async (key: string) => {
    return localStorage.getItem(key)
  },
  setItem: async (key: string, value: string) => {
    localStorage.setItem(key, value)
  },
  removeItem: async (key: string) => {
    localStorage.removeItem(key)
  },
}

export const webAdapter: ContactsAdapter = {
  getStorage: () => webStorage,

  requestContactsPermission: async () => {
    // Web doesn't need permission for localStorage
    return 'granted'
  },

  getContactsFromDevice: async () => {
    // Get contacts from localStorage
    const savedContacts = localStorage.getItem('contacts')
    if (savedContacts) {
      try {
        const contacts = JSON.parse(savedContacts)
        // Transform the local contacts format to match what the store expects
        return contacts.map((contact: any) => ({
          name: contact.name || contact.username || 'Unknown',
          phone:
            contact.phone !== 'N/A' ? contact.phone : contact.username || '',
        }))
      } catch (error) {
        console.error('Failed to parse saved contacts:', error)
        return []
      }
    }
    return []
  },

  // Web doesn't support widgets, so these methods are undefined
  // The shared store handles this gracefully by checking if they exist
  updateWidgetContacts: undefined,
  refreshWidgets: undefined,
}

