import { createJSONStorage, persist } from 'zustand/middleware'
import type { ContactsStore, Contact, ContactsAdapter } from './types'
import type { AuthStore } from '../auth/types'
import type { ApiClient } from '../../api/types'

const cleanPhone = (p: string): string =>
  (p || '').replace(/[\s\-().]/g, '')

/** Merge contact lists, de-duplicating by cleaned phone (first occurrence wins). */
const dedupeByPhone = <T extends { phone: string }>(lists: T[]): T[] => {
  const seen = new Set<string>()
  const out: T[] = []
  for (const item of lists) {
    const key = cleanPhone(item.phone)
    if (!key || seen.has(key)) continue
    seen.add(key)
    out.push(item)
  }
  return out
}

export const createContactsStore = (
  adapter: ContactsAdapter,
  useAuthStore: () => AuthStore,
  apiClient: ApiClient,
  displayBackendNotification?: (notification: {
    title: string
    body: string
    phone: string
  }) => void
) =>
  create<ContactsStore>()(
    persist(
      (set, get) => ({
        loading: false,
        contacts: [],
        manualContacts: [],
        hasInitialFetch: false,

        fetchContacts: async (options?: {
          skipPermissionRequest?: boolean
          showLoading?: boolean
        }) => {
          const { skipPermissionRequest = false, showLoading = true } =
            options || {}

          try {
            // Read the device address book if (and only if) we have permission.
            // A denied permission is not fatal — the user may still have
            // manually-added contacts to enrich.
            let deviceContacts: Array<{ name: string; phone: string }> = []
            let permissionGranted = skipPermissionRequest
            if (!skipPermissionRequest) {
              const status = await adapter.requestContactsPermission()
              permissionGranted = status === 'granted'
            }
            if (permissionGranted) {
              try {
                deviceContacts = await adapter.getContactsFromDevice()
              } catch (error) {
                console.error('Failed to read device contacts:', error)
              }
            }

            const token = useAuthStore.getState().token
            if (!token) {
              return
            }

            const manual = get().manualContacts || []
            const union = dedupeByPhone([
              ...deviceContacts.map(c => ({ name: c.name, phone: c.phone })),
              ...manual.map(c => ({ name: c.name, phone: c.phone })),
            ])

            if (union.length === 0) {
              set({ contacts: [], ...(showLoading && { loading: false }) })
              if (!get().hasInitialFetch) set({ hasInitialFetch: true })
              return []
            }

            if (showLoading) {
              set({ loading: true })
            }

            // See which contacts use the app
            const resp = await apiClient.post('/api/enrich_contacts', {
              contacts: union,
              token,
            })

            const contactsData: Contact[] = resp['contacts'].map((i: Contact) => ({
              ...i,
              phone: cleanPhone(i.phone),
            }))

            set({
              contacts: contactsData,
              ...(showLoading && { loading: false }),
            })

            // Save contacts to shared storage for widget access (if supported)
            try {
              if (adapter.updateWidgetContacts) {
                await adapter.updateWidgetContacts(contactsData)
                if (adapter.refreshWidgets) {
                  adapter.refreshWidgets()
                }
              }
            } catch (error) {
              console.error('Failed to save contacts to shared storage:', error)
            }

            // Register background task only after first successful fetch
            const currentState = get()
            if (!currentState.hasInitialFetch) {
              set({ hasInitialFetch: true })
            }

            return contactsData
          } catch (error) {
            console.error('Failed to fetch contacts:', error)
            if (showLoading) {
              set({ loading: false })
            }
            throw error
          }
        },

        addManualContact: async (name: string, phone: string) => {
          const token = useAuthStore.getState().token
          if (!token) {
            throw new Error('You must be signed in to add a contact')
          }
          const phoneClean = cleanPhone(phone)
          if (!phoneClean) {
            throw new Error('A phone number is required')
          }

          // Enrich the single contact so we know whether they have the app /
          // are available (and so the backend records the friendship edge).
          let enriched: Contact = {
            phone: phoneClean,
            name: name || phoneClean,
            has_app: false,
            available: false,
          }
          try {
            const resp = await apiClient.post('/api/enrich_contacts', {
              contacts: [{ name, phone: phoneClean }],
              token,
            })
            const first = resp['contacts']?.[0]
            if (first) {
              enriched = {
                phone: cleanPhone(first.phone),
                name: first.name || name || phoneClean,
                has_app: !!first.has_app,
                available: !!first.available,
              }
            }
          } catch (error) {
            console.error('Failed to enrich manual contact:', error)
            // Fall through and still add it locally.
          }

          // Upsert into both the persisted manual list and the visible list.
          const manual = (get().manualContacts || []).filter(
            c => cleanPhone(c.phone) !== enriched.phone
          )
          const contacts = (get().contacts || []).filter(
            c => cleanPhone(c.phone) !== enriched.phone
          )
          set({
            manualContacts: [...manual, enriched],
            contacts: [...contacts, enriched],
          })

          try {
            if (adapter.updateWidgetContacts) {
              await adapter.updateWidgetContacts(get().contacts)
              adapter.refreshWidgets?.()
            }
          } catch (error) {
            console.error('Failed to update widget after manual add:', error)
          }

          return enriched
        },

        removeManualContact: async (phone: string) => {
          const target = cleanPhone(phone)
          set({
            manualContacts: (get().manualContacts || []).filter(
              c => cleanPhone(c.phone) !== target
            ),
            contacts: (get().contacts || []).filter(
              c => cleanPhone(c.phone) !== target
            ),
          })
          try {
            if (adapter.updateWidgetContacts) {
              await adapter.updateWidgetContacts(get().contacts)
              adapter.refreshWidgets?.()
            }
          } catch (error) {
            console.error('Failed to update widget after manual remove:', error)
          }
        },

        refreshWidgetContacts: async () => {
          try {
            const contacts = get().contacts
            if (contacts && contacts.length > 0) {
              if (adapter.updateWidgetContacts) {
                await adapter.updateWidgetContacts(contacts)
                if (adapter.refreshWidgets) {
                  adapter.refreshWidgets()
                }
                return true
              } else {
                // Platform doesn't support widgets
                return true
              }
            } else {
              console.warn('No contacts available to share with widget')
              return false
            }
          } catch (error) {
            console.error('Failed to refresh widget contacts:', error)
            return false
          }
        },

        updateContactAvailability: async (
          phone: string,
          available: boolean
        ) => {
          const contacts = get().contacts
          const contact = contacts.find((c) => c.phone === phone)

          if (!contact) {
            console.warn(`Contact with phone ${phone} not found`)
            return
          }

          // Update contact availability
          const updatedContacts = contacts.map((c) =>
            c.phone === phone ? { ...c, available } : c
          )

          set({ contacts: updatedContacts })

          // Refresh widget with updated data
          try {
            await get().refreshWidgetContacts()
          } catch (error) {
            console.error('Failed to update widget contacts:', error)
          }

          return contact
        },

        handleFriendAvailable: async (data: { phone: string }) => {
          const phone = data.phone
          const contact = await get().updateContactAvailability(phone, true)

          if (contact && displayBackendNotification) {
            const contactName = contact.name || 'Someone'
            displayBackendNotification({
              title: `${contactName} is available!`,
              body: 'Give them a call',
              phone: phone,
            })
          }
        },

        handleFriendUnavailable: async (data: { phone: string }) => {
          const phone = data.phone
          await get().updateContactAvailability(phone, false)
          // No notification for unavailable status
        },
      }),

      {
        name: 'prelude-contacts-storage',
        storage: createJSONStorage(() => adapter.getStorage()),
        partialize: (state) =>
          Object.fromEntries(
            Object.entries(state).filter(
              ([key]) => !['Not to include'].includes(key)
            )
          ),
      }
    )
  )

