export interface Contact {
  phone: string
  name: string
  has_app: boolean
  available: boolean
  // Photo from the device's native address book for this phone number.
  // Device-local only — never sent to or stored on the backend.
  avatar_url?: string
  // Avatar the contact uploaded/set themselves in-app, returned by the
  // backend. Not populated yet (no upload endpoint/storage exists).
  app_avatar_url?: string
}

export interface ContactsStore {
  contacts: Contact[]
  // Contacts added by hand (independent of the device address book) so they
  // survive the periodic device re-sync and work without contacts permission.
  manualContacts: Contact[]
  loading: boolean
  hasInitialFetch: boolean

  // Core methods
  fetchContacts: (options?: {
    skipPermissionRequest?: boolean
    showLoading?: boolean
  }) => Promise<Contact[] | void>

  // Manually add/remove a contact by name + phone (phone must be E.164)
  addManualContact: (name: string, phone: string) => Promise<Contact>
  removeManualContact: (phone: string) => Promise<void>

  refreshWidgetContacts: () => Promise<boolean>

  // Availability update methods
  updateContactAvailability: (
    phone: string,
    available: boolean
  ) => Promise<Contact | undefined>

  // Notification handlers
  handleFriendAvailable: (data: { phone: string }) => Promise<void>
  handleFriendUnavailable: (data: { phone: string }) => Promise<void>
}

export interface ContactsAdapter {
  // Permission handling
  requestContactsPermission(): Promise<'granted' | 'denied' | 'undetermined'>

  // Contact retrieval
  getContactsFromDevice(): Promise<
    Array<{ name: string; phone: string; avatar_url?: string }>
  >

  // Storage
  getStorage(): any // AsyncStorage for RN, localStorage adapter for web

  // Widget functionality (optional - only supported on mobile)
  updateWidgetContacts?: (contacts: Contact[]) => Promise<void>
  refreshWidgets?: () => void
}
